#!/usr/bin/env python3
"""Authoring helper. Commits ready-to-serve HTML; deployment has no build step."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[2]
SITE=ROOT/'site'
BASE='https://serenity.sire.run'
nav='''<a class="skip" href="#main">Skip to content</a><header class="site-nav"><a class="brand" href="/"><img src="/assets/brand.svg" width="36" height="36" alt="">serenity</a><nav class="nav-links" aria-label="Main navigation"><a class="nav-product" href="/product/">Product</a><a href="/docs/">Docs</a><a href="/chat/">Setup help</a><a class="install" href="/get-started/">Install <span aria-hidden="true">↗</span></a></nav></header>'''
footer='''<footer class="site-footer"><span>Serenity · Apache-2.0 · Sire Run, Inc.</span><a href="https://github.com/sirerun/serenity">GitHub ↗</a><a href="/docs/privacy/">Privacy</a><a href="/brand/">Brand</a><a href="https://ndungu.dev">Made by David Ndungu ↗</a></footer>'''
ask='''<a class="ask-link" href="/chat/"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M20 11a8 8 0 0 1-8 8H4l1.6-4A8 8 0 1 1 20 11Z"/></svg>Ask about Serenity</a>'''
maker='''<section class="maker" aria-label="About the maker"><div><p class="eyebrow">The person behind the project</p><h2>Good AI needs<br>thoughtful engineering.</h2></div><div><p>I’m David Ndungu. I build software that makes AI useful in real work. Serenity is part of that work: keeping context available, decisions inspectable, and people in control.</p><p>Through my consultancy, I build custom AI automations for business workflows, connected to real tools with human approval gates.</p><a class="pill" href="https://ndungu.dev">Work with David ↗</a></div></section>'''
links=[('/get-started/','Installation'),('/docs/quickstart/','First local memory'),('/docs/connectors/','Connect your sources'),('/docs/models/','Models and cited answers'),('/docs/workflows/','Everyday workflows'),('/docs/ownership/','Your memory, your files'),('/docs/agents/','Agents and embedding'),('/docs/troubleshooting/','Troubleshooting'),('/docs/faq/','Common questions')]
def code(s):return '<pre data-copy><code>'+escape(s.strip())+'</code></pre>'
def note(s):return '<aside class="note">'+s+'</aside>'
def page(path,title,desc,body,docs=False,extras=''):
    sidebar='<aside class="doc-nav" aria-label="Documentation">'+''.join(f'<a href="{url}"'+(' aria-current="page"' if url==path else '')+f'>{label}</a>' for url,label in links)+'</aside>'
    content=('<div class="doc-layout">'+sidebar+'<article class="prose">'+body+'</article></div>') if docs else '<div class="prose">'+body+'</div>'
    text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#ececeb"><title>{escape(title.replace("<br>", " "))} — Serenity</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{BASE+path}"><link rel="icon" href="/assets/brand.svg" type="image/svg+xml"><meta property="og:title" content="{escape(title.replace("<br>", " "),quote=True)} — Serenity"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{BASE+path}"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script src="/assets/adoption.js" defer></script></head><body>{nav}<main class="page" id="main"><header class="page-header"><p class="eyebrow">Memory for agents and systems</p><h1>{title}</h1><p class="lede">{desc}</p></header>{content}</main>{extras}{footer}{ask}</body></html>'''
    out=SITE/path.strip('/')/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(text)
    pages.append({'url':BASE+path,'title':title,'description':desc,'html':body})
pages=[]
page('/get-started/','Set up the brain.<br>Work through your agent.','Install Serenity behind your agent or application. Start with a separate brain Git repository and a small set of sources.',
'''<h2 id="choose">Choose your install</h2><p>Your everyday interface is Codex CLI running in your brain repository, or a system that integrates Serenity. The commands below install and verify the memory layer. There is no standalone Serenity Brain app today.</p><p>Serenity is early software for macOS on Apple silicon and Linux on amd64 or arm64. It requires Git and an accessible operating-system keychain. Start with a small set of notes.</p>'''+note('<strong>Release or current source?</strong><p>The latest packaged release is v0.1.1. The guides on this site describe current source, which includes newer commands. Use the source install below for these guides, or consult the documentation at your release tag.</p>')+'''<h3 id="source">Current source · Go 1.26+</h3><p>Install from the main branch to use the workflows documented here:</p>'''+code('GOWORK=off go install github.com/sirerun/serenity/cmd/serenity@main\nserenity --help')+'''<p>Make sure your Go binary directory is on PATH. Run <code>go env GOBIN</code>; if it is empty, use the <code>bin</code> directory under <code>go env GOPATH</code>.</p><h3 id="homebrew">Packaged release · Homebrew</h3>'''+code('brew install sirerun/tap/serenity\nserenity --help')+'''<p>Homebrew installs the released version, which may not include the latest source workflows.</p><h3 id="downloads">Download a binary</h3><p><a href="https://github.com/sirerun/serenity/releases/latest">Choose your platform on GitHub Releases ↗</a>. Download the matching archive and <code>checksums.txt</code>, verify the archive checksum, extract it, and place <code>serenity</code> on PATH. Windows and Intel macOS are not packaged targets.</p><h2 id="next">Give your agent a brain</h2><p>Create a separate brain repository, verify its sources, then start Codex CLI there. For another system, choose the documented CLI, MCP, HTTP, or embedded interface.</p><a class="pill" href="/docs/quickstart/">Follow the quickstart →</a><p class="source-note">Source: <a href="https://github.com/sirerun/serenity/blob/main/README.md">README</a> and <a href="https://github.com/sirerun/serenity/releases">release artifacts</a>. Checked 7 September 2026.</p>''',True)
page('/docs/quickstart/','Create your agent’s brain.','Create a separate brain repository, verify a small set of sources, then open your agent in that repository.',
'''<h2 id="create">1. Create a brain</h2><p>A brain is a Git repository containing your memory. Keep it separate from the Serenity source checkout and the folder you will ingest.</p>'''+code('mkdir -p ~/my-brain\ncd ~/my-brain\nserenity init\nserenity doctor')+'''<p><code>init</code> creates the directory layout and <code>serenity.yml</code>, initializes Git, and saves an authentication token in your OS keychain. An unavailable keychain makes initialization fail; <a href="/docs/troubleshooting/">check the troubleshooting guide</a> if you run headless.</p><h2 id="connect">2. Connect one folder</h2><p>Edit the generated <code>serenity.yml</code>. Use an absolute path to a directory of notes outside the brain repository:</p>'''+code('connectors:\n  file:\n    path: /absolute/path/to/notes')+'''<p>Start with a small folder whose contents you know. That makes it easier to verify your first results.</p><h2 id="search">3. Sync and search</h2>'''+code('serenity sync\nserenity search "project priorities"\nserenity status')+'''<p><code>sync</code> imports sources and rebuilds the search index. It runs once. Files must have been unchanged for at least two seconds to be ingested. Full-text search does not require an API key or a model.</p><h2 id="anywhere">4. Select the brain explicitly</h2>'''+code('serenity -C ~/my-brain search "project priorities"')+'''<h2 id="agent">5. Start your agent in the brain repository</h2><p>With Codex CLI already installed, open it from the brain directory:</p>'''+code('cd ~/my-brain\ncodex')+'''<p>Ask the agent to read this brain’s configuration and use the documented Serenity CLI to search its sources. Starting an agent in the folder does not by itself configure MCP or enable models. See <a href="/docs/agents/">agents and embedding</a> for the available interfaces.</p><h2 id="next">Next: answers with citations</h2><p>Search finds source text. To extract claims and compose answers, configure models and run extraction as a separate step.</p><a class="pill" href="/docs/models/">Configure models →</a>'''+note('<strong>Choose your backup deliberately.</strong><p>Initialization installs a post-commit push hook. Add a private remote and configure its upstream if you want commits pushed there. Without a remote or another backup, the local repository is your only copy.</p>'),True)
page('/product/','The brain behind<br>your agent.','Serenity is a memory and context layer for agents and the systems you build. Your brain lives in a Git repository you own.',
'''<h2 id="fit">Where you actually work</h2><p>Start Codex CLI in your brain repository and work through the agent. Serenity supplies the memory tools underneath: bringing in sources, retrieving context, and preserving records beyond a conversation. You can also integrate it into another system, with that system providing the interface.</p><p>The brain repository holds your personal context. Keep it separate from the Serenity source-code repository.</p><h2 id="capture">Give the agent context worth keeping</h2><p>Notes, repository documentation, and email contain decisions and details a model cannot know on its own. Choose which sources the brain ingests and when they sync. Your agent can use that material through Serenity’s interfaces.</p><h2 id="answers">Keep the evidence with the answer</h2><p>Full-text search works without a model. With extraction and composition configured, Serenity can provide claims and cited answers to the agent or calling system. Citations let you inspect the original support.</p><h2 id="ownership">Own the memory behind the conversation</h2><p>Your brain’s durable records are inspectable files in Git. You choose the backup location and model providers. Model-assisted features send relevant context to the provider you configure.</p><h2 id="direction">Carry your constraints into other systems</h2><p>Serenity can check structured actions against recorded constraints, called precepts. An integrating system can use the result in its workflow. Free-text checking remains unverified; the documented structured-action contract defines what works today.</p><h2 id="interfaces">Two ways to use the same foundation</h2><ul><li><strong>Through an agent:</strong> run Codex CLI in the brain repository and give it access to the documented Serenity commands or MCP tools.</li><li><strong>Inside another system:</strong> integrate through the CLI, MCP, HTTP interfaces, or the read-only Go package. Your application owns the user experience.</li></ul><p><a href="/docs/agents/">Read the agent and embedding guide →</a></p><h2 id="inspiration">Inspired by gbrain</h2><p>Serenity was inspired by and builds on <a href="https://github.com/garrytan/gbrain">Garry Tan’s gbrain</a>. David Ndungu began the project after watching <a href="https://www.youtube.com/watch?v=eRrc1pUY5oU">Garry Tan: Own Your Intelligence</a>.</p><p>The idea that carried through: keep your context in your own custody and make it available to the agent doing your work. Serenity develops that foundation as a memory and context layer you can run and embed.</p><h2 id="app">A possible future Brain app</h2><p>We may create a Serenity Brain app in the future. It is a possibility, not an available product or a promised release. Today, Serenity runs behind your agent or inside another system. This website explains setup; its chat only answers questions about public documentation.</p><div class="actions"><a class="pill" href="/get-started/">Set up a brain →</a><a class="pill secondary" href="/docs/agents/">Explore integration</a></div>''',extras=maker)
page('/docs/','A clear path from<br>install to useful.','Set up a brain for Codex CLI, integrate Serenity into another system, and understand how context is stored and retrieved.',
'<div class="link-grid">'+''.join(f'<a class="link-item" href="{url}"><h3>{label} ↗</h3><p>{desc}</p></a>' for (url,label),desc in zip(links,['Choose current source or a packaged release.','Create a brain and search a notes folder.','Bring in files, repository docs, and Gmail.','Add extraction and answers with citations.','Repeatable commands for the workday.','Understand storage, backups, and providers.','Know the available interfaces and their limits.','Fix setup, indexing, and model problems.','Answers before you commit to a new tool.']))+'</div>'+note('<strong>Documentation scope</strong><p>These guides target current source, checked 7 September 2026. Packaged v0.1.1 predates some workflows. The <a href="https://github.com/sirerun/serenity">repository</a> is the source of truth as development continues.</p>'))
page('/docs/connectors/','Bring your sources.','Start narrow, verify what was imported, then expand your memory one source at a time.',
'''<h2 id="files">Local files</h2><p>Set one directory tree under <code>connectors.file.path</code> in <code>serenity.yml</code>. Keep that directory outside your brain repository to avoid ingesting generated memory as new source material.</p>'''+code('connectors:\n  file:\n    path: /absolute/path/to/notes')+'''<p>Run <code>serenity sync</code> after edits. Files must be unchanged for two seconds. This is a polling workflow, not a continuous watcher.</p><h2 id="git">Git repository documentation</h2><p>The Git connector accepts multiple <code>connectors.git_repo</code> entries. It imports README files and documentation under <code>docs/</code> at HEAD. It is not a whole-codebase code index.</p><p>Use the <a href="https://github.com/sirerun/serenity/blob/main/docs/connectors/gitrepo.md">repository connector configuration reference</a> for the exact entry schema and polling behavior.</p><h2 id="gmail">Gmail via IMAP</h2><p>Gmail with an app password is the certified mailbox setup. Enable Google account 2-Step Verification and create an app password, then authenticate:</p>'''+code('serenity connectors auth imap --email you@gmail.com')+'''<p>The password is stored in your operating-system keychain; only the email address is written to the brain configuration. The terminal prompt may echo input, so use the documented password-manager pipe if you need to avoid visible input.</p><p>The connector polls one account’s INBOX per brain. OAuth, multiple simultaneous accounts, and other mailbox providers are not certified by this guide. Re-run authentication to replace a revoked app password.</p><h2 id="verify">Check the setup</h2>'''+code('serenity connectors status\nserenity sync\nserenity status')+'''<p><code>sync</code> imports sources. <code>extract</code> separately turns sources into claims after models are configured.</p><p class="source-note">References: <a href="https://github.com/sirerun/serenity/tree/main/docs/connectors">connector documentation</a>.</p>''',True)
page('/docs/models/','Find the source.<br>Then ask the question.','Local search is useful on its own. Add model-assisted extraction and composition when you want cited answers.',
'''<h2 id="defaults">Start with the defaults</h2><p>New brains use <code>none@v0</code> for extraction, embeddings, and composition. Model-dependent tasks are disabled until configured. Importing sources does not automatically extract claims.</p><h2 id="configure">Configure extraction and composition</h2><p>The default provider for these tasks is OpenRouter. Set <code>OPENROUTER_API_KEY</code> in the process environment using your normal secret-management workflow. Choose model identifiers supported by your provider, then use versioned pins:</p>'''+code("serenity config set-model extraction '<model-id>@<version>'\nserenity config set-model composer '<model-id>@<version>'\nserenity extract\nserenity ask \"What are my current project priorities?\"")+'''<p>Replace the placeholders with actual model pins. Credentials come from environment variables, not <code>serenity.yml</code>. Model calls may incur provider charges.</p><h2 id="embeddings">Embeddings are separate</h2><p>Embedding configuration uses an OpenAI-compatible endpoint and separate credentials. It does not follow the extraction/composer provider setting. See the <a href="https://github.com/sirerun/serenity/blob/main/docs/providers.md">provider reference</a> before configuring an embedding model.</p><p>The search CLI currently uses full-text search even when an embedding model is pinned. Answer composition can use query embeddings when configured.</p><h2 id="local">Using a local provider</h2><p>Local OpenAI-compatible endpoints can be configured for supported provider paths. Endpoint choice, model naming, and the extraction/composer adapter selection matter. Follow the exact provider reference rather than assuming every pin routes identically.</p><h2 id="verify">Read answers with the evidence</h2><p>A citation gives you a way to inspect support; it does not make every generated claim correct. Open the cited source, check that the context matches, and use direct search when you need the original wording.</p>'''+note('<strong>Your data and your provider</strong><p>Extraction sends source context, and answer composition sends relevant query context, to the configured provider. Local files alone do not make a cloud-model workflow fully local. See <a href="/docs/ownership/">ownership and privacy</a>.</p>'),True)
page('/docs/workflows/','Memory in your workflow.','These commands are building blocks for your agent or integrating system. Run them directly when setting up or checking a brain.',
'''<p>In everyday use, work through Codex CLI in the brain repository or through your own application. Give that agent or system an explicit workflow for refreshing sources, retrieving context, and checking evidence.</p><h2 id="refresh">After updating your notes</h2>'''+code('serenity -C ~/my-brain sync\nserenity -C ~/my-brain search "release decision"')+'''<p>Sync brings in changed sources. Search checks that the material you expect is available. If you configured extraction, run it separately:</p>'''+code('serenity -C ~/my-brain extract')+'''<h2 id="recall">Before starting a task</h2>'''+code('serenity -C ~/my-brain search "project constraints"\nserenity -C ~/my-brain ask "What did I decide about this project?"')+'''<p><code>ask</code> needs composition models. Check citations before carrying an answer into another tool or a consequential decision.</p><h2 id="check">Check structured actions</h2><p>For a brain with active constraint precepts, check actions against those recorded constraints:</p>'''+code("serenity check --actions '[{\"action\":\"spend_over\",\"params\":{\"amount\":500}}]' --json")+'''<p>The amount here is example input, not a default spending policy. The result depends on the precepts in your brain.</p><div class="table-wrap"><table><thead><tr><th>Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>0</td><td>Pass or no applicable constraints. Inspect the verdict.</td></tr><tr><td>2</td><td>A recorded constraint was violated.</td></tr><tr><td>1</td><td>Unverified or an error.</td></tr></tbody></table></div><p>No applicable constraints does not mean an action is safe. Free-text plans currently return unverified because a classification provider is not wired into that CLI path.</p><h2 id="health">When something feels wrong</h2>'''+code('serenity -C ~/my-brain doctor\nserenity -C ~/my-brain status\nserenity -C ~/my-brain connectors status')+'''<p>Read the status before repeating a large ingest. Start troubleshooting with one source and a query whose answer you already know.</p>''',True)
page('/docs/ownership/','Your memory.<br>Your repository.','Know what stays on disk, what can leave your machine, and what you need to back up.',
'''<h2 id="files">A brain you own</h2><p>Serenity stores personal memory in a Git repository. Sources and memory records are inspectable, and Git preserves a history of committed changes. The runtime search index supports retrieval; the repository is the durable record.</p><h2 id="backup">Choose a backup location</h2><p>Initialization installs a post-commit push hook. If you add a private remote and configure its upstream, commits can be pushed there. Without a remote or another backup, the local repository is your only copy. Keep personal brains private.</p><h2 id="models">Understand model traffic</h2><p>Full-text search works without model calls. When you enable extraction or answer composition, source or query context is sent to the provider you configure. Review that provider’s retention and data-use terms. Local endpoint configuration is available for supported adapter paths.</p><h2 id="credentials">Credentials have their own home</h2><p>Serenity’s authentication token and Gmail app password use the OS keychain. Model-provider credentials are read from the process environment. Do not write API keys into source notes or commit them to your brain.</p><h2 id="delete">Think beyond one file</h2><p>Deleting a working-tree file is not the same as removing it from Git history, backups, or a provider’s records. If your goal is complete removal of sensitive material, account for every copy. The connector and source lifecycle documentation describes supported behavior; do not assume automatic erasure across systems.</p><h2 id="website">This website is separate from your brain</h2><p>The adoption chat answers questions about Serenity’s public documentation. It does not connect to your personal brain. Do not paste private notes, credentials, or confidential source material into it.</p><a href="/docs/privacy/">Read website and chat privacy →</a>''',True)
page('/docs/agents/','Run behind your agent.<br>Embed in your system.','Use Codex CLI in your brain repository, or connect your own system to Serenity’s memory and context interfaces.',
'''<h2 id="codex">Work through Codex CLI</h2><p>Initialize a separate brain using the <a href="/docs/quickstart/">quickstart</a>, then start your installed Codex CLI there:</p>'''+code('cd ~/my-brain\ncodex')+'''<p>You interact with Codex. The brain repository supplies persistent context, and Serenity supplies commands and tools for working with that context. Have the agent use the documented CLI, or configure an MCP connection explicitly. Opening a directory alone does not install an integration.</p><h2 id="cli">CLI access for agents and systems</h2><p>An agent that can run commands can use the documented search and ask workflows against a brain you explicitly make available. Use <code>-C</code> to select the brain, keep authentication private, and review any command that changes personal records.</p><h2 id="mcp">MCP is still evolving</h2><p><code>serenity -C ~/my-brain serve --stdio</code> starts the MCP transport. Current source also supports authenticated Streamable HTTP with <code>serve --http</code>. Against a real brain, current source exposes five memory tools: recall, remember, entity, synthesize, and forget. Use -C to select that brain. If the path is not a brain, the transport serves the bare protocol with an empty registry. The older packaged release differs.</p><p><code>serenity connect</code> reports token status; automatic MCP configuration and hook installation are not yet implemented in the documented CLI. Token rotation uses <code>serenity connect --rotate-token</code>.</p><h2 id="http">Server interfaces</h2><p>Server work is progressing independently of the packaged release. Consult the current <a href="https://github.com/sirerun/serenity/blob/main/docs/operator/server.md">HTTP operator guide</a> and <a href="https://github.com/sirerun/serenity/blob/main/docs/operator/mcp.md">MCP operator guide</a> for authentication, bind configuration and exact exposed capabilities.</p><h2 id="embedded">Embedding in Go</h2><p>Go applications can use the read-only <code>pkg/serenity</code> package to access a brain in process. The <a href="https://github.com/sirerun/serenity/blob/main/docs/adr/012-embedded-read-facade-single-writer.md">embedding contract</a> defines its scope and ownership rules.</p>'''+note('<strong>Check the interface you intend to use.</strong><p>A protocol implementation, a CLI wrapper, and a packaged release may have different capabilities during active development. Verify your version and the corresponding reference before configuring an agent.</p>'),True)
page('/docs/troubleshooting/','Get back to the useful part.','Start with the smallest reproducible setup: one brain, one folder, and one known phrase.',
'''<h2 id="not-found">The shell cannot find serenity</h2><p>Check the installation completed, then check PATH. Source installs use <code>go env GOBIN</code>, or the <code>bin</code> directory under GOPATH when GOBIN is empty. Open a fresh shell after changing PATH.</p><h2 id="keychain">Initialization fails at the keychain</h2><p>Initialization requires an accessible OS keychain. On a headless or locked session, verify that your keychain service is available and unlocked. Do not work around this by storing the authentication token in a public repository.</p><h2 id="empty">Search finds nothing</h2><ol><li>Confirm <code>-C</code> points to the intended brain.</li><li>Check the absolute <code>connectors.file.path</code> in that brain’s configuration.</li><li>Allow files to remain unchanged for at least two seconds.</li><li>Run <code>serenity sync</code>, then <code>serenity status</code>.</li><li>Search for a distinctive phrase that is actually in a source.</li></ol><h2 id="models">Ask or extraction is disabled</h2><p>New brains start with <code>none@v0</code> model pins. Configure extraction and composition, provide credentials in the process environment, and run <code>extract</code> after <code>sync</code>. See <a href="/docs/models/">model setup</a>.</p><h2 id="mail">Gmail authentication stopped working</h2><p>Re-run <code>serenity connectors auth imap --email you@gmail.com</code> with a valid app password. Confirm 2-Step Verification and app-password availability on your account. The connector is certified for Gmail app passwords, not OAuth.</p><h2 id="version">A documented command is missing</h2><p>Packaged v0.1.1 predates newer source workflows. Check <code>serenity --help</code> and use the <a href="/get-started/#source">current-source installation</a> if you need the guides on this site.</p><h2 id="report">Report a reproducible problem</h2><p>Include your platform, install method, command, and a small sanitized example. Remove private notes, credentials, and account information before posting.</p><a class="pill" href="https://github.com/sirerun/serenity/issues">Open a GitHub issue ↗</a>''',True)
faq=[('Is there a Serenity Brain app?','No standalone Serenity Brain app is available today. We may build one in the future, but there is no promised release. Today you work through an agent such as Codex CLI or a system that embeds Serenity.'),('What inspired Serenity?','Serenity was inspired by and builds on <a href="https://github.com/garrytan/gbrain">Garry Tan’s gbrain</a>. David started it after watching <a href="https://www.youtube.com/watch?v=eRrc1pUY5oU">Own Your Intelligence</a>.'),('What is Serenity?','A memory and context layer that runs behind agents or inside other systems. Start Codex CLI in a separate brain Git repository, or integrate Serenity into your application. You own the brain’s records.'),('Do I need an account?','Not for local full-text search. Model-assisted features need access to a configured model provider. Gmail ingestion needs mailbox authentication.'),('Is it free?','Serenity is open-source software under Apache-2.0. Model providers and any infrastructure you choose may charge separately. There is no required Serenity subscription for the local CLI.'),('Does everything stay on my machine?','Local full-text search needs no model. Extraction and composed answers send context to the configured provider. A Git remote receives the commits you configure the brain to push. Choose each connection deliberately.'),('Can I use it without AI?','Yes. Import local sources and use full-text search without a model or API key.'),('Which computers are supported?','Packaged releases target Apple silicon macOS and Linux amd64/arm64. Current source builds require Go 1.26 or later. Git and an accessible OS keychain are required.'),('Does it automatically watch my files?','The sync command runs once. Run it again to poll your configured sources. Do not assume it stays running as a watcher.'),('Can it index every file in a Git repository?','The repository connector imports README files and documentation under docs/ at HEAD. It is not a general source-code indexing tool.'),('Is it production-ready?','Serenity is under active development. Start with a small brain and verify the workflows you need. Packaged releases and current source differ; the getting-started guide makes that distinction explicit.'),('Can this website chat read my brain?','No. The adoption chat uses public product documentation and helps with installation. Do not paste private notes or credentials into it.'),('Can David help with custom automation?','Yes. Visit ndungu.dev to discuss custom AI automations for business workflows. Serenity is one example of David’s open-source engineering work.')]
page('/docs/faq/','Good questions.<br>Plain answers.','The practical details before you add Serenity to your workflow.',''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)+'<p style="margin-top:32px"><a href="/chat/">Ask another question →</a></p>',True)
page('/docs/privacy/','Website and chat privacy.','This public website helps you understand and install Serenity. It is separate from any personal brain you create.',
'''<h2 id="static">The website</h2><p>Pages are static HTML, CSS and JavaScript hosted on GitHub Pages. Hosting and asset providers receive ordinary connection information when your browser requests content. The landing page loads background media from the supplied CloudFront hosts and fonts from Google Fonts.</p><h2 id="chat">The adoption chat</h2><p>The chat is intended for questions about public Serenity documentation. Submitting a question sends its text and the recent conversation to the Serenity chat service on AWS Lambda. Model-assisted answers send that question, recent conversation, and relevant public documentation to OpenRouter and its selected model provider. If a model answer is unavailable, the chat labels its response as documentation search.</p><p>Do not submit passwords, API keys, confidential source material, or personal brain contents. The website chat does not have access to your local Serenity installation.</p><p>The chat keeps the conversation in browser memory for the current page session, not persistent browser storage. The service does not store conversation transcripts. Rate limiting stores a salted hash derived from the visitor IP and request counts with an expiry of approximately 25 hours; AWS TTL removal is asynchronous. Hosting and model-provider operational records and retention policies still apply.</p><h2 id="browser">Browser storage and controls</h2><p>Chat theme preferences may be stored in your browser. Microphone input, when supported, begins only after you activate the voice control and grant browser permission. Your browser’s speech recognition service may process audio remotely.</p><h2 id="contact">Questions</h2><p>For product issues, use the <a href="https://github.com/sirerun/serenity/issues">GitHub issue tracker</a> with sanitized examples. For work with the creator, visit <a href="https://ndungu.dev">ndungu.dev</a>.</p>''')
page('/brand/','Collected calm.','A quiet identity for context that stays with its owner.',
'''<div class="brand-showcase" style="display:flex;align-items:center;gap:32px;padding:40px 0"><img src="/assets/brand.svg" width="100" height="100" alt="Serenity open-ring S mark"><span style="font-size:64px;letter-spacing:-3px">serenity</span></div><h2>The mark</h2><p>Two open arcs form an S: a continuous thread, with room for something new. Use the mark on a quiet surface, with at least a quarter of its width clear on every side.</p><div class="actions"><a class="pill" href="/assets/brand.svg" download>Download SVG mark</a><a class="pill secondary" href="/assets/wordmark.svg" download>Download wordmark</a><a href="/assets/brand-mono.svg" download>Monochrome</a><a href="/assets/brand-light.svg" download>Light mark</a></div><h2>The palette</h2><p>Paper (#ececeb) gives the work space. Ink (#222222) keeps it readable. Rose (#a83451) identifies Serenity. Lilac and ember appear in the supplied moving glass surfaces.</p><h2>The voice</h2><p>Plain words, concrete next steps, and a source for every claim. Never invent a performance number or turn an unfinished capability into a promise.</p><h2>The line</h2><p class="lede">Keep your context. Find your calm.</p><p>Serenity is created by <a href="https://ndungu.dev">David Ndungu</a> and published by Sire Run, Inc. Downloading these assets does not imply endorsement.</p>''')
(SITE/'content.json').write_text(json.dumps(pages,indent=2))
(SITE/'CNAME').write_text('serenity.sire.run\n')
(SITE/'.nojekyll').touch()
(SITE/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
(SITE/'llms.txt').write_text('# Serenity\n\nMemory and context for agents and embedded systems, in a brain Git repository you own. Start Codex CLI in that repository or integrate Serenity into your own system. No standalone Brain app is available today. Inspired by and building on Garry Tan’s gbrain. Current-source documentation; packaged release v0.1.1 differs.\n\n'+''.join(f'- [{p["title"].replace("<br>"," ")}]({p["url"]}): {p["description"]}\n' for p in pages))
(SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p+'</loc></url>' for p in ['/']+[p['url'].removeprefix(BASE) for p in pages]+['/chat/'])+'</urlset>')
print('Wrote',len(pages),'static pages and documentation corpus')
